from pathlib import Path
import json,difflib,re,hashlib
P=Path(__file__).resolve().parent;old=(P/'manuscript-v2.md').read_text()
edits=[('For these 178 records, the answer to the overall question is a positive, moderately sized descriptive association: Pearson r was 0.546 and the slope was 1.560.','For these 178 records, the overall association is positive: Pearson r was 0.546 and the slope was 1.560.','Removes a subjective magnitude label; retains the same fixed dataset, positive direction, r and slope. No stronger claim is introduced.'),('Rank and omission checks make a single outlier or a purely linear scaling explanation less compelling as the sole explanation of the positive direction, but they do not identify a mechanism.','The positive direction was retained with rank correlations and after every single-record omission from the pooled and adjusted fits. These checks do not identify a mechanism.','Replaces a vague explanation with exact checks already performed and reported. Does not claim every class-specific omission was fitted; explicitly says pooled and adjusted. Retains the no-mechanism boundary.')]
edits.extend([
('transparent linear-algebra code was used instead of installing an additional statistical stack.','OLS coefficients were computed with NumPy least squares, and HC3 covariance matrices were evaluated from the design matrices, residuals, and leverage values.','Replaces installation context with the actual executed scientific calculation. Same six formal model fits and covariance formula; no statistical stack falsely claimed.'),
('The adjusted row uses the partial Pearson correlation; a single adjusted Spearman statistic was not specified.','The adjusted row uses the partial Pearson correlation; the dash indicates that this regression adjustment does not supply a Spearman coefficient.','Changes a workflow-status phrase to the scientific meaning of the empty cell. No adjusted rank statistic is fabricated or substituted for the actual linear partial correlation.'),
('| Class adjusted | 178 | 0.319 | Not specified | 0.940 | 0.492 to 1.389 |','| Class adjusted | 178 | 0.319 | - | 0.940 | 0.492 to 1.389 |','All five numeric entries retain their values. The dash refers to the accompanying caption; no result was removed because this cell contained no computed Spearman result.'),
('A Codex AI agent performed the computations and assisted with drafting and source-guided checks; human authorship and external peer review are not asserted. Scientific Agent Skills provided procedural guidance [3]. No new samples were collected, and no ethics approval, funding, conflict declaration, or author approval is inferred.','A Codex AI agent performed the computations and assisted with drafting. The accompanying code and full-precision outputs document the analyses. No new samples were collected.','Retains truthful AI assistance, actual reproducibility materials and lack of new sample collection. Moves internal procedural attribution and unknown author/review/declaration states to the companion delivery record; does not claim any approval or external verification.'),
('[3] Kassis T, Agarwal V, He Y, Patel D, Brueckner AM. Scientific Agent Skills: A Library of Procedural Knowledge for Research Agents. 2026. arXiv:2609.00065. https://doi.org/10.48550/arXiv.2609.00065. Current record checked 18 October 2026.','[2] statsmodels developers. OLSResults.HC3_se. Official statsmodels documentation. https://www.statsmodels.org/stable/generated/statsmodels.regression.linear_model.OLSResults.HC3_se.html. Accessed 18 October 2026. Cited for the HC3 formula; statsmodels software was not used in the calculations.','Moves the procedural-library reference to the companion attribution and bibliography. The two scientific/data references remain intact; no scientific support citation is deleted. This after quote is the actual final reference-list ending.')
])
new=old
for before,after,assess in edits:assert before in new;new=new.replace(before,after)
(P/'manuscript-final.md').write_text(new)
coverage=json.loads((P/'manuscript-coverage-v2.json').read_text())
for q in coverage['questions']:
 q['conclusion']['path']='manuscript-final.md'
 for before,after,_ in edits:q['conclusion']['quote']=q['conclusion']['quote'].replace(before,after)
for e in coverage['experiments']:
 for kind in ['methods','results']:e[kind]['path']='manuscript-final.md'
coverage['reviewed_coverage']='manuscript-coverage-v2.json';(P/'manuscript-coverage-final.json').write_text(json.dumps(coverage,indent=2))
report={'unresolved_required':[],'meaning_checks':[{'before':a,'after':b,'assessment':c} for a,b,c in edits],'unchanged_checks':{'objects':'alcohol, color intensity and numeric cultivar classes unchanged','scope':'complete original178historicalrecords, descriptive no causal/population unchanged','direction':'overall/class/adjusted positive retained','numbers':'all scientific result/method numeric tokens unchanged; removed procedural citation numbering/year/identifier moved to companion record','methods':'all primary and robustness methods retained','null_vs_untested':'no untested relation changed into zero/absence; broad quadraticCI and interactionp retained','citations':'two scientific/data references retained; procedural library citation moved to companion record with its existing bibliography entry','experiment_coverage':'E1/E2 exactMethods/Resultslocations unchanged; both conclusions still present','internal_process':'No Skill receipts or phase/budget narrative added'},'review_scope':'Two optional precision edits from completed professional review plus parent editorial notes on scientific methods and internal-process cleanup; no new scientific test or fullreview','before_sha256':hashlib.sha256(old.encode()).hexdigest(),'after_sha256':hashlib.sha256(new.encode()).hexdigest()}
nums=lambda s:re.findall(r'(?<![A-Za-z])[-+]?\d+(?:\.\d+)?(?:\^-?\d+)?',s)
# Verify all numeric tokens outside the removed procedural-only material remain unchanged.
old_science=old.replace(edits[-2][0],edits[-2][1]).replace(edits[-1][0],'')
new_science=new
assert nums(old_science)==nums(new_science)
(P/'expression-meaning-checks.json').write_text(json.dumps(report,indent=2))
(P/'expression-actual.diff').write_text(''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='manuscript-v2.md',tofile='manuscript-final.md')))
(P/'expression-record.md').write_text('# Final expression and meaning review\nApplied source principles of coherent evidence-bound narrative and keeping implementation logs outside the paper, subject to the fixed-question/scientific-integrity contract. Retained every required result, nonpositive/uncertain diagnostic, actual limitation and reference; did not apply source suggestions to change the question or suppress inconvenient evidence. Two reviewedprecisionedits only. Exactnumericsequence equality checked in code, and actualbefore/afterclaims inspected for objects,scope,direction,causalstrength,methods,untestedversusnull and experimentcoverage. These are Agent assessments, not human approval. Fullactualdiff and quote-spanassessments preserved.\n')
